---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Inline text diff: The agent's edits to a piece of copy, accepted or rejected one by one.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change inline-text-diff.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './inline-text-diff.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', className]} data-c="inline-text-diff" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="itd panel">
  <div class="itd-h"><div class="itd-ht"><b>Pricing intro</b><span class="muted itd-st" aria-live="polite">4 edits to review</span></div><div class="itd-a"><button class="pill ghost sm itd-no">Reject all</button><button class="pill primary sm itd-ok">Accept all</button></div></div>
  <p class="itd-t"></p>
  <p class="itd-f" aria-live="polite"></p>
  <div class="itd-bar" role="dialog" aria-label="Edit">
    <p class="itd-why"><svg class="itd-wi" viewBox="0 0 24 24" aria-hidden="true"><path class="a" d="M12 3.6 2.6 19.9h18.8z"/><path class="b" d="M12 9.6v4.4M12 17v.01"/></svg><span></span></p>
    <div class="itd-bb"><button class="pill primary sm itd-acc"><svg class="i xs"><use href="#i-check"/></svg>Accept</button><button class="pill ghost sm itd-rej"><svg class="i xs"><use href="#i-x"/></svg>Reject</button></div>
  </div>
</div>
  </Fragment></div>
</div>
<script>
  import './inline-text-diff.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Inline text diff ---------- */
/* a piece of copy with the agent's edits marked inline, struck and added; each edit opens a small toolbar to accept or
   reject it, and an edit the agent isn't sure of says why */
.itd{position:relative;width:100%;max-width:440px;margin:0 auto;padding:var(--dm-s-4);display:flex;flex-direction:column;gap:var(--dm-s-3)}
.itd-h{display:flex;align-items:center;gap:var(--dm-s-3)}
.itd-ht{flex:1;min-width:0;display:flex;flex-direction:column}
.itd-ht b{font-weight:500;font-size:14px}
.itd-st{font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.itd-a{display:flex;gap:6px;flex:none}
/* a narrow card (a phone) gives the title and the count their whole line, and the two buttons a row of their own under
   them, ending on the content's right edge, so the count is never cut short */
.itd{container-type:inline-size}
@container (max-width:300px){.itd-h{flex-wrap:wrap;row-gap:var(--dm-s-3)}.itd-ht{flex:1 1 100%}.itd-a{margin-left:auto}}
.itd-t{margin:0;font-size:14px;line-height:1.8;color:var(--dm-fg)}
/* an edit's words start where the line starts (the text's own column), so their tints reach out round them with a shadow
   rather than pushing them in with padding */
.itd-c{padding:2px 0;border-radius:var(--dm-r-tiny,5px);cursor:pointer;outline:0;transition:background .16s;-webkit-box-decoration-break:clone;box-decoration-break:clone}
/* the edit whose toolbar is open: a fill a step stronger than the hover, so it reads as picked */
.itd-c.on{background:var(--dm-hover)}
@media (hover:hover) and (pointer:fine){.itd-c:hover{background:var(--dm-row)}}
.itd-c:focus-visible{box-shadow:0 0 0 2px var(--dm-focus)}
/* removed words in the red text colour on its tint, struck with the bright red mark; added words in the green text colour on
   its tint (each 4.5:1 on its tint); an addition the agent isn't sure of in the warning's text colour on its tint */
/* (each tint is laid over the surface, so the quiet fill under an open edit never shows through it and lowers its contrast;
   the 2px of padding round the words is taken back by a margin, so the words keep their place on the line) */
.itd-c del{color:var(--dm-bad);text-decoration:line-through;text-decoration-color:var(--dm-bad-mark);text-decoration-thickness:1px;background:linear-gradient(var(--dm-bad-bg),var(--dm-bad-bg)),var(--dm-surface);border-radius:var(--dm-r-tiny,3px);padding:0 2px;margin:0 6px 0 -2px}
.itd-c ins{color:var(--dm-ok);text-decoration:none;background:linear-gradient(var(--dm-ok-bg),var(--dm-ok-bg)),var(--dm-surface);border-radius:var(--dm-r-tiny,3px);padding:0 2px;margin-left:-2px}
.itd-c.unsure ins{color:var(--dm-warn);background:linear-gradient(var(--dm-warn-bg),var(--dm-warn-bg)),var(--dm-surface)}
.itd-c.acc del,.itd-c.rej ins{display:none}
.itd-c.acc ins,.itd-c.rej del{color:inherit;background:none;text-decoration:none;margin:0;padding:0}
/* no room is kept for the end (owner, 18 Nov): the card eases shorter as edits fold into the text and grows for the note at
   the end (grow()); the toolbar opens out of it, so nothing clips it */
.itd.growing{overflow:visible}
/* an edit's toolbar opens under its last line, or over its first when the stage has no room below */
.itd-bar{position:absolute;left:0;top:0;z-index:5;display:flex;flex-direction:column;gap:var(--dm-s-2);padding:var(--dm-s-2);width:max-content;max-width:260px;border-radius:var(--dm-r-in);background:var(--dm-raised);box-shadow:var(--dm-shadow-pop);opacity:0;transform:translateY(-4px);visibility:hidden;pointer-events:none;transition:opacity .16s,transform .32s var(--dm-ease),visibility 0s .32s}
.itd-bar.up{transform:translateY(4px)}
.itd-bar.open{opacity:1;transform:none;visibility:visible;pointer-events:auto;transition-delay:0s}
/* an edit the agent isn't sure of: its toolbar is a warning notice (owner, 18 Nov): a faint warning tint, the filled warning
   sign in the bright orange, the words in the text colour, and the answer that settles it, Reject, as .pill.warn, with Accept
   the white button beside it */
.itd-bar.unsure{background:linear-gradient(color-mix(in srgb,var(--dm-warn-bg) 45%,transparent),color-mix(in srgb,var(--dm-warn-bg) 45%,transparent)),var(--dm-surface)}
.itd-why{margin:0;display:flex;gap:var(--dm-s-2);padding:2px 2px 0;font-size:12.5px;line-height:18px;color:var(--dm-fg)}
.itd-wi{width:16px;height:16px;flex:none;margin-top:1px;overflow:visible}
/* (a step of --dm-warn in the bright orange keeps the sign at 3:1 on the notice's tint, as Attachment tray's strip tick does) */
.itd-wi .a{fill:color-mix(in srgb,var(--dm-warn-mark) 85%,var(--dm-warn));stroke:color-mix(in srgb,var(--dm-warn-mark) 85%,var(--dm-warn));stroke-width:2;stroke-linejoin:round}
.itd-wi .b{fill:none;stroke:var(--dm-surface);stroke-width:2.2;stroke-linecap:round}
.itd-bb{display:flex;gap:6px}
.itd-bar.unsure .itd-bb{justify-content:flex-end}
/* nothing in it grows or shrinks when it is pressed (owner, 18 Nov); Clean's ink primary alone presses */
.itd .pill:active{transform:none}
.itd-bar.unsure .itd-acc{background:var(--dm-surface);color:var(--dm-fg);box-shadow:var(--dm-on-tint-btn)}
@media (hover:hover) and (pointer:fine){.itd-bar.unsure .itd-acc:hover{background:var(--dm-surface);box-shadow:var(--dm-on-tint-btn-h)}}
/* the end: a neutral line with the green tick (owner, 18 Nov), only once every edit is decided */
/* the line saying how the review went sits under a hairline in Soft and Blueprint (owner, 21 Nov), 12px from it on each side */
.itd-f{margin:0;display:flex;align-items:center;gap:6px;padding-top:var(--dm-s-4);border-top:1px solid color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:13px;line-height:20px;color:var(--dm-fg)}
.itd-f:empty{display:none}
/* Clean: the line saying how the review went is the card's off-white foot strip (owner, 21 Nov), its words 16px in */
:root[data-style="clean"] .itd-f,:root [data-style="clean"] .itd-f,:root [data-style="clean"].itd-f{padding-top:0;border-top:0}
:root[data-style="clean"] .itd.panel .itd-f,:root [data-style="clean"] .itd.panel .itd-f,:root [data-style="clean"].itd.panel .itd-f{margin:var(--dm-s-1) -16px -16px;padding:calc(var(--dm-strip-y) + 5px) 16px;background:var(--dm-strip);border-top:1px solid var(--dm-line);border-radius:0 0 var(--dm-r-card) var(--dm-r-card);line-height:18px}
/* empty, it takes no room (the gap above it is taken back) but stays in place, so the end is read out when it comes */
.itd-f:empty{min-height:0;margin-top:calc(-1 * var(--dm-s-3))}
.itd-f svg{flex:none;color:var(--dm-ok-mark)}
/* Clean (owner, 19 Nov): its content 16px from every edge; the toolbar is a round popover, its corners concentric with its
   28px buttons 8px in (22px), scaling and fading from the edit; on an unsure edit Accept is Clean's flat white button */
:root[data-style="clean"] .itd.panel,:root [data-style="clean"] .itd.panel,:root [data-style="clean"].itd.panel{padding:16px}
/* the head sits over a hairline that runs edge to edge, 16px under it, and the text starts 16px under the hairline (owner,
   22 Nov: a divider at the top for Clean, so its parts read as segments, as the foot strip does at the bottom) */
:root[data-style="clean"] .itd.panel .itd-h,:root [data-style="clean"] .itd.panel .itd-h,:root [data-style="clean"].itd.panel .itd-h{margin-inline:-16px;padding:0 16px 16px;border-bottom:1px solid var(--dm-line)}
:root[data-style="clean"] .itd-ht b,:root [data-style="clean"] .itd-ht b,:root [data-style="clean"].itd-ht b{line-height:20px}
:root[data-style="clean"] .itd-st,:root [data-style="clean"] .itd-st,:root [data-style="clean"].itd-st{line-height:18px}
:root[data-style="clean"] .itd-c,:root [data-style="clean"] .itd-c,:root [data-style="clean"].itd-c{transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .itd-c.on,:root [data-style="clean"] .itd-c.on,:root [data-style="clean"].itd-c.on{background:var(--dm-row-on)}
:root[data-style="clean"] .itd-bar,:root [data-style="clean"] .itd-bar,:root [data-style="clean"].itd-bar{border-radius:var(--dm-r-card);transform:translateY(-4px) scale(.96);transform-origin:top left;transition:opacity var(--dm-t-fast) var(--dm-ease),transform var(--dm-t) var(--dm-ease),visibility 0s var(--dm-t)}
:root[data-style="clean"] .itd-bar.up,:root [data-style="clean"] .itd-bar.up,:root [data-style="clean"].itd-bar.up{transform:translateY(4px) scale(.96);transform-origin:bottom left}
:root[data-style="clean"] .itd-bar.open,:root [data-style="clean"] .itd-bar.open,:root [data-style="clean"].itd-bar.open{transform:none;transition-delay:0s}
:root[data-style="clean"] .itd-bar.unsure .itd-acc,:root [data-style="clean"] .itd-bar.unsure .itd-acc,:root [data-style="clean"].itd-bar.unsure .itd-acc{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .itd-bar.unsure .itd-acc:hover,:root [data-style="clean"] .itd-bar.unsure .itd-acc:hover,:root [data-style="clean"].itd-bar.unsure .itd-acc:hover{color:var(--dm-fg);background:linear-gradient(180deg,var(--dm-btn2-1),var(--dm-btn2-2));box-shadow:var(--dm-btn2-depth)}}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .itd-bar.unsure .itd-acc:hover,:root [data-style="clean"] .itd-bar.unsure .itd-acc:hover,:root [data-style="clean"].itd-bar.unsure .itd-acc:hover{box-shadow:var(--dm-btn2-hover)}}
:root[data-style="clean"] .itd-bar.unsure .itd-acc:active,:root [data-style="clean"] .itd-bar.unsure .itd-acc:active,:root [data-style="clean"].itd-bar.unsure .itd-acc:active{box-shadow:var(--dm-btn2-press)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, giveBack, grow, popRoom, swap } from '../core/core.js';
DM.def('inline-text-diff', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chk}', I('check','xs')).replace('{x}', I('x','xs'));
  // the copy, and the agent's edits to it: what it said, what the agent suggests, and why, when the agent isn't sure
  const T = [{ o:'Pick', n:'Choose' }, ' a plan that ', { o:'fits your team', n:'grows with your studio' }, '. Every plan ', { o:'includes', n:'comes with' }, ' unlimited projects, and ', { o:'you can cancel at any time', n:'your first month is free', why:'Not in the pricing brief: there is no free month' }, '.'];
  const E = T.filter(x => typeof x === 'object');
  const root = $('.itd', r), tx = $('.itd-t', r), st = $('.itd-st', r), bar = $('.itd-bar', r), why = $('.itd-why', r), f = $('.itd-f', r), acts = $('.itd-a', r), acc = $('.itd-acc', r), rej = $('.itd-rej', r);
  // no room is kept for the end: the card eases shorter as edits fold into the text, and grows for the note at the end.
  // grow() starts once the card's entrance (which scales it from .98 in Clean) has ended, so it measures its real size
  Promise.resolve().then(() => Promise.all(root.getAnimations().map(a => a.finished.catch(() => {})))).then(() => { if (!c.dead && root.isConnected) c.offs.push(grow(root)); });
  tx.innerHTML = T.map(x => typeof x === 'string' ? x : `<span class="itd-c${x.why ? ' unsure' : ''}" role="button" tabindex="0" aria-haspopup="dialog" aria-expanded="false"><del>${x.o}</del><ins>${x.n}</ins></span>`).join('');
  const chunks = $$('.itd-c', tx);
  E.forEach((e, i) => { e.s = ''; chunks[i].setAttribute('aria-label', `Edit ${i + 1} of ${E.length}: ${e.o}, suggested ${e.n}`); });
  let cur = -1;
  function tally(){
    const n = E.filter(e => !e.s).length, a = E.filter(e => e.s === 'acc').length;
    swap(st, n === E.length ? `${n} edits to review` : n ? `${n} of ${E.length} left` : `${a} accepted, ${E.length - a} rejected`);
    // the note comes in a beat after the card starts to grow for it, so it never shows past the card's edge
    if (!n && !f.textContent){ acts.hidden = true; f.innerHTML = `${I('ok','xs')}<span>Saved to Pricing v4</span>`; enter(f, 220); }
  }
  const close = () => { bar.classList.remove('open'); bar.inert = true; chunks.forEach(x => { x.classList.remove('on'); x.setAttribute('aria-expanded', false); }); cur = -1; };
  // the toolbar opens under the edit's last line, or over its first when the stage or the page has no room below it;
  // inside a scaled preview the offsets are divided by its scale
  function open(i){
    cur = i; const el = chunks[i], e = E[i];
    chunks.forEach((x, k) => { x.classList.toggle('on', k === i); x.setAttribute('aria-expanded', k === i); });
    why.hidden = !e.why; $('span', why).textContent = e.why || '';
    // an edit the agent isn't sure of: the toolbar is a warning notice, and Reject, which settles it, is .pill.warn
    bar.classList.toggle('unsure', !!e.why);
    acc.className = 'pill sm itd-acc ' + (e.why ? 'line' : 'primary'); rej.className = 'pill sm itd-rej ' + (e.why ? 'warn' : 'ghost');
    const rb = root.getBoundingClientRect(), k = rb.width / root.offsetWidth || 1, rs = el.getClientRects(), cr = rs[rs.length - 1] || el.getBoundingClientRect(), c0 = rs[0] || cr;
    const room = popRoom(el), up = cr.bottom + 6 + bar.offsetHeight * k > room.bottom - 8 && c0.top - 6 - bar.offsetHeight * k >= room.top + 8;
    bar.inert = false; bar.classList.toggle('up', up); void bar.offsetWidth; bar.classList.add('open');
    bar.style.left = Math.max(12, Math.min(((up ? c0 : cr).left - rb.left) / k, root.offsetWidth - bar.offsetWidth - 12)) + 'px';
    bar.style.top = (up ? (c0.top - rb.top) / k - 6 - bar.offsetHeight : (cr.bottom - rb.top) / k + 6) + 'px';
  }
  // each decision folds an edit into plain text, and the last swaps the actions for a short note; the card eases to fit
  function decide(i, s){ E[i].s = s; chunks[i].classList.remove('acc', 'rej'); chunks[i].classList.add(s); tally(); }
  // a click anywhere else on the page can close the toolbar between the story's taps, and then there is no edit to decide
  // the focus goes back to the edit, with a ring only when the answer came from the keyboard (a click never leaves one)
  const pick = s => { const i = cur; if (i < 0) return; const back = bar.contains(document.activeElement); close(); decide(i, s); if (back) giveBack(chunks[i]); };
  // Enter or Space opens an edit's toolbar with the focus on Accept, as a dialog takes the focus; Escape brings it back
  chunks.forEach((el, i) => { el.onclick = () => cur === i ? close() : open(i); el.onkeydown = ev => { if (ev.key === 'Enter' || ev.key === ' '){ ev.preventDefault(); el.click(); if (cur === i) $('.itd-acc', r).focus({ preventScroll:true }); } }; });
  // the left and right arrows move between Accept and Reject
  c.on(bar, 'keydown', ev => { const bs = $$('button', bar), j = bs.indexOf(document.activeElement), d = { ArrowRight:1, ArrowDown:1, ArrowLeft:-1, ArrowUp:-1 }[ev.key];
    if (j < 0) return; const to = d ? bs[(j + d + bs.length) % bs.length] : ev.key === 'Home' ? bs[0] : ev.key === 'End' ? bs[bs.length - 1] : null;
    if (to){ ev.preventDefault(); to.focus({ preventScroll:true }); } });
  $('.itd-acc', r).onclick = () => pick('acc');
  $('.itd-rej', r).onclick = () => pick('rej');
  $('.itd-ok', r).onclick = () => { close(); E.forEach((e, i) => { if (!e.s) decide(i, 'acc'); }); };
  $('.itd-no', r).onclick = () => { close(); E.forEach((e, i) => { if (!e.s) decide(i, 'rej'); }); };
  // Escape or a click elsewhere closes the toolbar
  c.on(r, 'keydown', ev => { if (ev.key === 'Escape' && cur >= 0){ const el = chunks[cur]; close(); el.focus({ preventScroll:true }); } });
  c.on(document, 'pointerdown', ev => { if (cur >= 0 && !bar.contains(ev.target) && !ev.target.closest('.itd-c')) close(); });
  bar.inert = true; tally();
  // the preview's story: accept two edits, read why the agent isn't sure of one and reject it, then accept the rest
  c.story(async s => {
    await s.beat(4);
    await s.tap(chunks[0]); await s.beat(2); await s.tap($('.itd-acc', r)); await s.beat(1);
    await s.tap(chunks[1]); await s.beat(2); await s.tap($('.itd-acc', r)); await s.beat(1);
    await s.tap(chunks[3]); await s.beat(5); await s.tap($('.itd-rej', r)); await s.beat(3);
    await s.tap($('.itd-ok', r)); s.away();
    await s.beat(3);
  });
});
